// Pomodoro timer logic as plain functions over an immutable state object.
// The current time is passed in (`now`, in ms) so the logic stays pure and testable.

export const DEFAULT_DURATION_MS = 25 * 60 * 1000;

export function createTimer(durationMs = DEFAULT_DURATION_MS) {
  return { durationMs, remainingMs: durationMs, startedAt: null };
}

export function isRunning(state) {
  return state.startedAt !== null;
}

export function getRemaining(state, now) {
  if (!isRunning(state)) return state.remainingMs;
  return Math.max(0, state.remainingMs - (now - state.startedAt));
}

export function isDone(state, now) {
  return getRemaining(state, now) === 0;
}

export function start(state, now) {
  if (isRunning(state) || state.remainingMs === 0) return state;
  return { ...state, startedAt: now };
}

export function pause(state, now) {
  if (!isRunning(state)) return state;
  return { ...state, remainingMs: getRemaining(state, now), startedAt: null };
}

export function reset(state) {
  return createTimer(state.durationMs);
}

export function formatTime(ms) {
  const totalSeconds = Math.ceil(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  createTimer,
  start,
  pause,
  reset,
  getRemaining,
  isRunning,
  isDone,
  formatTime,
} from "./timer.js";

const MIN = 60 * 1000;

test("start runs the countdown from the full duration", () => {
  const timer = start(createTimer(25 * MIN), 1000);

  assert.equal(isRunning(timer), true);
  assert.equal(getRemaining(timer, 1000), 25 * MIN);
  assert.equal(getRemaining(timer, 1000 + 90_000), 25 * MIN - 90_000);
  assert.equal(formatTime(getRemaining(timer, 1000 + 90_000)), "23:30");
});

test("start is a no-op while already running", () => {
  const timer = start(createTimer(MIN), 0);
  assert.equal(start(timer, 5000), timer);
});

test("countdown stops at zero and a finished timer cannot be restarted", () => {
  const timer = start(createTimer(MIN), 0);

  assert.equal(getRemaining(timer, 2 * MIN), 0);
  assert.equal(isDone(timer, 2 * MIN), true);

  const finished = pause(timer, 2 * MIN);
  assert.equal(start(finished, 3 * MIN), finished);
});

test("pause freezes the remaining time and start resumes from it", () => {
  let timer = start(createTimer(25 * MIN), 0);
  timer = pause(timer, 10_000);

  assert.equal(isRunning(timer), false);
  assert.equal(getRemaining(timer, 10_000), 25 * MIN - 10_000);
  assert.equal(getRemaining(timer, 999_999), 25 * MIN - 10_000);

  timer = start(timer, 50_000);
  assert.equal(getRemaining(timer, 55_000), 25 * MIN - 15_000);
});

test("pause is a no-op when not running", () => {
  const timer = createTimer(MIN);
  assert.equal(pause(timer, 1000), timer);
});

test("reset restores the full duration and stops the timer", () => {
  const running = start(createTimer(5 * MIN), 0);
  const paused = pause(running, 30_000);

  for (const timer of [running, paused]) {
    const fresh = reset(timer);
    assert.equal(isRunning(fresh), false);
    assert.equal(getRemaining(fresh, 10 * MIN), 5 * MIN);
    assert.deepEqual(fresh, createTimer(5 * MIN));
  }
});

test("formatTime rounds partial seconds up", () => {
  assert.equal(formatTime(25 * MIN), "25:00");
  assert.equal(formatTime(59_001), "01:00");
  assert.equal(formatTime(500), "00:01");
  assert.equal(formatTime(0), "00:00");
});
